<?php
namespace App\Http\Controllers\Operations;use App\Http\Controllers\Controller;use App\Models\{GuestServiceRequest,Stay,User};use App\Services\Operations\GuestServiceManager;use Illuminate\Http\Request;
class GuestServiceController extends Controller{public function index(){ $p=auth()->user()->property_id;return view('operations.guest-services.index',['requests'=>GuestServiceRequest::with(['room','guest','assignee'])->where('property_id',$p)->latest('requested_at')->paginate(50),'stays'=>Stay::with(['room','guest'])->where('property_id',$p)->where('status','in_house')->get(),'staff'=>User::where('property_id',$p)->orderBy('name')->get()]);}public function store(Request $r){$p=auth()->user()->property_id;$d=$r->validate(['stay_id'=>'nullable|integer','request_type'=>'required|string|max:60','details'=>'nullable|string','priority'=>'required|in:low,normal,high,urgent','charge_amount'=>'nullable|numeric|min:0','assigned_to'=>'nullable|integer','due_at'=>'nullable|date']);$stay=!empty($d['stay_id'])?Stay::where('property_id',$p)->findOrFail($d['stay_id']):null;GuestServiceRequest::create($d+['property_id'=>$p,'room_id'=>$stay?->room_id,'guest_id'=>$stay?->guest_id,'status'=>$d['assigned_to']?'accepted':'new','requested_at'=>now(),'created_by'=>auth()->id(),'charge_amount'=>$d['charge_amount']??0]);return back()->with('success','Guest service request created.');}public function status(Request $r,GuestServiceRequest $guestServiceRequest,GuestServiceManager $manager){abort_unless($guestServiceRequest->property_id===auth()->user()->property_id,403);$d=$r->validate(['status'=>'required|in:new,accepted,in_progress,completed,cancelled','assigned_to'=>'nullable|integer','due_at'=>'nullable|date','completion_notes'=>'nullable|string']);$manager->updateStatus($guestServiceRequest,$d['status'],auth()->id(),$d['assigned_to']??null,$d['completion_notes']??null);if(array_key_exists('due_at',$d))$guestServiceRequest->update(['due_at'=>$d['due_at']]);return back()->with('success','Guest service request updated.');}}
